import{az as s,P as n,Q as t,aQ as p}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"其他/学习路线/软技能/技术管理.md","filePath":"其他/学习路线/软技能/技术管理.md","lastUpdated":1785339991000}'),e={name:"其他/学习路线/软技能/技术管理.md"};function l(d,a,i,r,c,o){return n(),t("div",null,[...a[0]||(a[0]=[p(`<h2 id="技术管理转型" tabindex="-1">技术管理转型 <a class="header-anchor" href="#技术管理转型" aria-label="Permalink to “技术管理转型”">​</a></h2><p><a href="https://book.douban.com/subject/4076564/" target="_blank" rel="noreferrer">格鲁夫给经理人的第一课</a></p><p>从技术骨干转型为技术管理者是程序员职业发展的重要路径之一。这一转变要求从&quot;自己做好&quot;转向&quot;让团队做好&quot;，工作重心从代码编写扩展到团队建设、项目管理和战略规划。</p><h2 id="管理者角色认知" tabindex="-1">管理者角色认知 <a class="header-anchor" href="#管理者角色认知" aria-label="Permalink to “管理者角色认知”">​</a></h2><h3 id="角色转变" tabindex="-1">角色转变 <a class="header-anchor" href="#角色转变" aria-label="Permalink to “角色转变”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>技术骨干 → 技术管理者</span></span>
<span class="line"><span></span></span>
<span class="line"><span>关注点变化：</span></span>
<span class="line"><span>- 从&quot;写好代码&quot;到&quot;团队产出&quot;</span></span>
<span class="line"><span>- 从&quot;个人技术&quot;到&quot;团队技术栈&quot;</span></span>
<span class="line"><span>- 从&quot;解决具体问题&quot;到&quot;制定流程规范&quot;</span></span>
<span class="line"><span>- 从&quot;被动接受任务&quot;到&quot;主动规划方向&quot;</span></span>
<span class="line"><span>- 从&quot;技术深度&quot;到&quot;技术广度+管理&quot;</span></span></code></pre></div><h3 id="管理者核心职责" tabindex="-1">管理者核心职责 <a class="header-anchor" href="#管理者核心职责" aria-label="Permalink to “管理者核心职责”">​</a></h3><table tabindex="0"><thead><tr><th>职责</th><th>说明</th><th>占比参考</th></tr></thead><tbody><tr><td>团队建设</td><td>招聘、培养、绩效管理</td><td>30%</td></tr><tr><td>项目管理</td><td>排期、风险控制、资源协调</td><td>25%</td></tr><tr><td>技术决策</td><td>架构评审、技术选型</td><td>20%</td></tr><tr><td>跨部门协作</td><td>与产品、设计、后端沟通</td><td>15%</td></tr><tr><td>团队文化</td><td>技术分享、代码规范、文档</td><td>10%</td></tr></tbody></table><h2 id="团队管理" tabindex="-1">团队管理 <a class="header-anchor" href="#团队管理" aria-label="Permalink to “团队管理”">​</a></h2><h3 id="_1v1-沟通" tabindex="-1">1v1 沟通 <a class="header-anchor" href="#_1v1-沟通" aria-label="Permalink to “1v1 沟通”">​</a></h3><p>定期与团队成员进行一对一沟通，了解状态和诉求。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>1v1 议题模板：</span></span>
<span class="line"><span>1. 近期工作状态如何？（有无困难、压力）</span></span>
<span class="line"><span>2. 当前项目的进展和阻碍？</span></span>
<span class="line"><span>3. 对团队/公司有什么建议？</span></span>
<span class="line"><span>4. 个人成长方向和需要的支持？</span></span>
<span class="line"><span>5. 下阶段的重点目标和期望？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>频率：每 2 周一次，每次 30-45 分钟</span></span>
<span class="line"><span>原则：倾听为主，少说多听，保密信任</span></span></code></pre></div><h3 id="绩效管理" tabindex="-1">绩效管理 <a class="header-anchor" href="#绩效管理" aria-label="Permalink to “绩效管理”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>绩效评估维度：</span></span>
<span class="line"><span>- 业务贡献：需求交付质量与效率</span></span>
<span class="line"><span>- 技术能力：代码质量、技术深度</span></span>
<span class="line"><span>- 团队协作：沟通、帮助他人、Code Review</span></span>
<span class="line"><span>- 主观能动性：主动发现问题、提出改进</span></span>
<span class="line"><span>- 成长进步：相比上一周期的提升</span></span>
<span class="line"><span></span></span>
<span class="line"><span>绩效面谈要点：</span></span>
<span class="line"><span>1. 基于事实和数据，避免主观印象</span></span>
<span class="line"><span>2. 先肯定成绩，再指出不足</span></span>
<span class="line"><span>3. 共同制定改进计划</span></span>
<span class="line"><span>4. 明确下阶段期望和资源支持</span></span></code></pre></div><h3 id="人才培养" tabindex="-1">人才培养 <a class="header-anchor" href="#人才培养" aria-label="Permalink to “人才培养”">​</a></h3><table tabindex="0"><thead><tr><th>培养方式</th><th>说明</th><th>适用对象</th></tr></thead><tbody><tr><td>技术分享</td><td>定期内部技术分享会</td><td>全员</td></tr><tr><td>结对编程</td><td>老带新结对开发</td><td>初中级</td></tr><tr><td>项目历练</td><td>给有潜力的人挑战性任务</td><td>中高级</td></tr><tr><td>导师制</td><td>指定导师定期指导</td><td>新人</td></tr><tr><td>外部培训</td><td>会议、课程、认证</td><td>核心成员</td></tr></tbody></table><h2 id="技术决策" tabindex="-1">技术决策 <a class="header-anchor" href="#技术决策" aria-label="Permalink to “技术决策”">​</a></h2><h3 id="架构评审流程" tabindex="-1">架构评审流程 <a class="header-anchor" href="#架构评审流程" aria-label="Permalink to “架构评审流程”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 发起评审：编写技术方案文档</span></span>
<span class="line"><span>2. 预审：核心成员提前阅读反馈</span></span>
<span class="line"><span>3. 正式评审：全员讨论，记录决策</span></span>
<span class="line"><span>4. 修订确认：根据反馈调整方案</span></span>
<span class="line"><span>5. 落地执行：按方案实施，跟踪结果</span></span>
<span class="line"><span></span></span>
<span class="line"><span>评审要点：</span></span>
<span class="line"><span>- 方案是否满足业务需求</span></span>
<span class="line"><span>- 是否有过度设计或设计不足</span></span>
<span class="line"><span>- 性能、安全、可维护性是否达标</span></span>
<span class="line"><span>- 是否有回滚方案</span></span>
<span class="line"><span>- 对现有系统的影响范围</span></span></code></pre></div><h3 id="技术债务管理" tabindex="-1">技术债务管理 <a class="header-anchor" href="#技术债务管理" aria-label="Permalink to “技术债务管理”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>技术债分类：</span></span>
<span class="line"><span>- 有意债务：为赶进度主动选择的妥协</span></span>
<span class="line"><span>- 无意债务：因能力不足或疏忽产生</span></span>
<span class="line"><span>- 过时债务：技术演进导致的老旧代码</span></span>
<span class="line"><span></span></span>
<span class="line"><span>管理策略：</span></span>
<span class="line"><span>1. 建立技术债清单，定期评估优先级</span></span>
<span class="line"><span>2. 每个迭代预留 10%-20% 时间还债</span></span>
<span class="line"><span>3. 新功能开发时顺带重构相关模块</span></span>
<span class="line"><span>4. 重大债务制定专项重构计划</span></span></code></pre></div><h2 id="常见转型挑战" tabindex="-1">常见转型挑战 <a class="header-anchor" href="#常见转型挑战" aria-label="Permalink to “常见转型挑战”">​</a></h2><table tabindex="0"><thead><tr><th>挑战</th><th>表现</th><th>应对策略</th></tr></thead><tbody><tr><td>放不下代码</td><td>事必躬亲，不信任团队</td><td>学会授权，聚焦管理</td></tr><tr><td>沟通困难</td><td>技术思维强，表达弱</td><td>刻意练习表达和倾听</td></tr><tr><td>时间碎片化</td><td>会议多，没整块时间</td><td>集中处理，保护专注时间</td></tr><tr><td>角色定位模糊</td><td>既写代码又管理</td><td>明确职责，合理分配精力</td></tr><tr><td>团队信任不足</td><td>成员不服管理</td><td>用专业能力 + 公平公正建立信任</td></tr></tbody></table><h2 id="管理者能力模型" tabindex="-1">管理者能力模型 <a class="header-anchor" href="#管理者能力模型" aria-label="Permalink to “管理者能力模型”">​</a></h2><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>技术管理者三层能力：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一层：执行力</span></span>
<span class="line"><span>- 任务拆分与分配</span></span>
<span class="line"><span>- 进度跟踪与风险控制</span></span>
<span class="line"><span>- 质量保障</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二层：领导力</span></span>
<span class="line"><span>- 团队愿景与目标对齐</span></span>
<span class="line"><span>- 激励与赋能</span></span>
<span class="line"><span>- 冲突管理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三层：战略力</span></span>
<span class="line"><span>- 技术规划与路线图</span></span>
<span class="line"><span>- 组织能力建设</span></span>
<span class="line"><span>- 业务理解与商业判断</span></span></code></pre></div><h2 id="转型时间线" tabindex="-1">转型时间线 <a class="header-anchor" href="#转型时间线" aria-label="Permalink to “转型时间线”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>重点</th></tr></thead><tbody><tr><td>适应期</td><td>0-3 个月</td><td>角色认知转换，建立信任</td></tr><tr><td>探索期</td><td>3-6 个月</td><td>建立管理流程，梳理团队现状</td></tr><tr><td>成型期</td><td>6-12 个月</td><td>团队稳定，形成自己的管理风格</td></tr><tr><td>成熟期</td><td>1-2 年</td><td>主动规划，团队能力持续提升</td></tr></tbody></table>`,27)])])}const x=s(e,[["render",l]]);export{u as __pageData,x as default};
